/**
 * Display formatting shared by every view. Mirrors the Engage switchboard's
 * rules so both consoles read the same.
 */
import { digitsOf } from './raw';

/** Placeholder for an empty table cell. */
export const EMPTY_CELL = '-';

/** Seconds elapsed from an epoch-ms start to `now`, never negative. */
export function secondsSince(start: number | null | undefined, now: number): number {
  if (start == null || !Number.isFinite(start)) return 0;
  return Math.max(0, Math.floor((now - start) / 1000));
}

/** m:ss, rolling to h:mm:ss past an hour (0:45, 12:03, 1:03:14). */
export function formatElapsed(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds <= 0) return '0:00';
  const s = Math.floor(seconds);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  if (h > 0) return `${h}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}`;
  return `${m}:${String(sec).padStart(2, '0')}`;
}

/** m:ss with minutes uncapped (63:14) - the KPI "Longest" and wallboard style. */
export function formatMinSec(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds <= 0) return '0:00';
  const s = Math.floor(seconds);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

/** Call-card timer: MM:SS, then HH:MM:SS from an hour, then "Nd Nh" from a day. */
export function formatTimer(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) return '00:00';
  const s = Math.floor(seconds);
  const d = Math.floor(s / 86400);
  if (d > 0) return `${d}d ${Math.floor((s % 86400) / 3600)}h`;
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  const mm = String(m).padStart(2, '0');
  const ss = String(sec).padStart(2, '0');
  return h > 0 ? `${String(h).padStart(2, '0')}:${mm}:${ss}` : `${mm}:${ss}`;
}

/** Roster age: 45s / 12m / 11h / 8d / 99d+; "" for zero or less. */
export function formatStateAge(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds <= 0) return '';
  const s = Math.floor(seconds);
  if (s < 60) return `${s}s`;
  if (s < 3600) return `${Math.floor(s / 60)}m`;
  if (s < 86400) return `${Math.floor(s / 3600)}h`;
  const d = Math.floor(s / 86400);
  return d < 100 ? `${d}d` : '99d+';
}

/** Minutes (as the statistics API reports talk time) to m:ss. */
export function minutesToClock(minutes: number): string {
  if (!Number.isFinite(minutes) || minutes <= 0) return '0:00';
  return formatElapsed(Math.round(minutes * 60));
}

/** NANP formatting for 10 and 11 digit numbers; anything else unchanged. */
export function formatPhone(raw: string): string {
  const v = (raw ?? '').trim();
  if (!v) return '';
  const d = digitsOf(v);
  if (d.length === 10 && d === v.replace(/[^0-9]/g, '') && /^[0-9+()\-\s.]+$/.test(v)) {
    return `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`;
  }
  if (d.length === 11 && d.startsWith('1') && /^[0-9+()\-\s.]+$/.test(v)) {
    return `(${d.slice(1, 4)}) ${d.slice(4, 7)}-${d.slice(7)}`;
  }
  return v;
}

export function plural(n: number, one: string, many = `${one}s`): string {
  return `${n} ${n === 1 ? one : many}`;
}

const dateTimeFmt = new Intl.DateTimeFormat(undefined, {
  month: 'short',
  day: 'numeric',
  year: 'numeric',
  hour: 'numeric',
  minute: '2-digit',
});

const timeFmt = new Intl.DateTimeFormat(undefined, {
  hour: 'numeric',
  minute: '2-digit',
  second: '2-digit',
});

export function formatDateTime(ms: number | null | undefined): string {
  if (ms == null || !Number.isFinite(ms)) return EMPTY_CELL;
  return dateTimeFmt.format(new Date(ms));
}

export function formatClockTime(ms: number): string {
  return timeFmt.format(new Date(ms));
}

/** "just now" / "12s ago" / "3m ago" for freshness labels. */
export function formatAgo(ms: number | null, now: number): string {
  if (ms == null) return 'not yet';
  const s = Math.max(0, Math.floor((now - ms) / 1000));
  if (s <= 2) return 'just now';
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  return `${Math.floor(s / 3600)}h ago`;
}

/** Percent with one decimal, trimmed ("78.1%", "100%"). */
export function formatPercent(v: number | null | undefined): string {
  if (v == null || !Number.isFinite(v)) return EMPTY_CELL;
  const r = Math.round(v * 10) / 10;
  return `${Number.isInteger(r) ? r.toFixed(0) : r.toFixed(1)}%`;
}
