/**
 * One shared 1-second clock. Timers, wait bands and the KPI strip read it
 * through `useNow()`; nothing else re-renders on the tick, so the data tree is
 * not redrawn every second just to move a few timers.
 */
import { useSyncExternalStore } from 'react';

let now = Date.now();
const listeners = new Set<() => void>();
let timer: number | null = null;

function start(): void {
  if (timer != null) return;
  timer = window.setInterval(() => {
    now = Date.now();
    for (const l of listeners) l();
  }, 1000);
}

function stop(): void {
  if (timer == null || listeners.size) return;
  window.clearInterval(timer);
  timer = null;
}

function subscribe(cb: () => void): () => void {
  listeners.add(cb);
  start();
  return () => {
    listeners.delete(cb);
    stop();
  };
}

function snapshot(): number {
  return now;
}

/** Current time in ms, updated once a second. */
export function useNow(): number {
  return useSyncExternalStore(subscribe, snapshot, snapshot);
}
